INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Projektstrukturplan (PSP) ein wesentliches Element im Projektmanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Organisiert das Projekt"}, {"text": "Nein", "correct": false, "because": "Er ist grundlegend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das primäre Ziel des Projektstrukturplans?', 3, '[{"text": "Projekt in Teilbereiche aufgliedern", "correct": true, "because": "Schafft Struktur"}, {"text": "Kosten direkt kalkulieren", "correct": false, "because": "Späterer Schritt"}, {"text": "Team motivieren", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der PSP dient der Übersicht. b) Er wird nur im Controlling genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, alle Phasen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten enthält der PSP?', 4, '[{"text": "Hauptprojekte", "correct": true, "because": "Oberste Ebene"}, {"text": "Unklare Aufgaben", "correct": false, "because": "Widerspricht Struktur"}, {"text": "Arbeitspakete", "correct": true, "because": "Kleinste Einheiten"}, {"text": "Teilprojekte", "correct": true, "because": "Zwischenebenen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne PSP effektiv gesteuert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur fehlt"}, {"text": "Ja", "correct": false, "because": "Risiko von Unklarheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase nutzt den PSP am intensivsten?', 3, '[{"text": "Planung", "correct": true, "because": "Definiert Struktur"}, {"text": "Initiierung", "correct": false, "because": "Ziele werden gesetzt"}, {"text": "Durchführung", "correct": false, "because": "Umsetzung folgt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der PSP nur für IT-Projekte geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Projekte"}, {"text": "Ja", "correct": false, "because": "Universelle Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat der PSP in der Durchführung?', 3, '[{"text": "Grundlage für Aufgabenverteilung", "correct": true, "because": "Definiert Zuständigkeiten"}, {"text": "Zeitplan direkt erstellen", "correct": false, "because": "Planungsaufgabe"}, {"text": "Ergebnisse präsentieren", "correct": false, "because": "Abschlussaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der PSP zeigt Abhängigkeiten. b) Er ist nur für große Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist eine Folge, wenn der PSP fehlt?', 3, '[{"text": "Unstrukturierte Projektarbeit", "correct": true, "because": "Fehlende Gliederung"}, {"text": "Schnellere Umsetzung", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kostenreduktion", "correct": false, "because": "Unübersichtlichkeit steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der PSP während des Projekts angepasst werden?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibilität erforderlich"}, {"text": "Nein", "correct": false, "because": "Anpassung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt einen PSP-Eintrag?', 3, '[{"text": "1.1.2 Serverkonfiguration", "correct": true, "because": "Klar und hierarchisch"}, {"text": "Irgendwas konfigurieren", "correct": false, "because": "Zu vage"}, {"text": "Team soll etwas tun", "correct": false, "because": "Nicht strukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der PSP nur für den Projektstart relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzen über alle Phasen"}, {"text": "Ja", "correct": false, "because": "Projektweite Bedeutung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein PSP?', 4, '[{"text": "Hierarchische Struktur", "correct": true, "because": "Fördert Übersicht"}, {"text": "Unklare Aufgaben", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Nummerierung", "correct": true, "because": "Kodierungssystem"}, {"text": "Definierte Arbeitspakete", "correct": true, "because": "Spezifiziert Aufgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der PSP schriftlich erstellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt den PSP?', 3, '[{"text": "Excel für Struktur", "correct": true, "because": "Visualisiert Hierarchie"}, {"text": "Keine Software", "correct": false, "because": "Fehlt Übersicht"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der PSP ohne Arbeitspakete funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Kernbestandteil fehlt"}, {"text": "Ja", "correct": false, "because": "Unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erleichtert die Nutzung des PSP?', 3, '[{"text": "Klar definierte Ziele", "correct": true, "because": "Fördern Struktur"}, {"text": "Unklare Anforderungen", "correct": false, "because": "Erschweren Gliederung"}, {"text": "Mangelnde Kommunikation", "correct": false, "because": "Verhindert Klarheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der PSP unterstützt die Zeitplanung. b) Er ist nur für technische Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil des PSP?', 3, '[{"text": "Bessere Projektsteuerung", "correct": true, "because": "Fördert Koordination"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Übersicht", "correct": false, "because": "Fördert Klarheit"}]');
